#include <iostream>

using namespace std;

int sumOfDigits(int x) {
    int sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, s;
    if (!(cin >> n >> m >> s)) return 0;

    int ans = -1;
    for (int i = m; i >= n; --i) {
        if (sumOfDigits(i) == s) {
            ans = i;
            break;
        }
    }

    cout << ans << "\n";

    return 0;
}
